const rows = $input.all().map(i => i.json);
const numeros = [...new Set(rows.map(r => String(r.telefone)))];
return [{ json: { numeros, rows } }];

const items = $input.all().map(i => i.json);
let lista = [];
if (items.length === 1) {
  const j = items[0];
  lista = Array.isArray(j) ? j : (j.data || j.result || [j]);
} else {
  lista = items.flatMap(j => Array.isArray(j) ? j : (j.data || j.result || [j]));
}

const digits = s => String(s || '').replace(/\D/g, '');

// variantes com e sem o 9 (problema classico BR)
function variantes(num) {
  const d = digits(num);
  const set = new Set([d]);
  if (d.length === 13 && d.substr(4, 1) === '9') set.add(d.substr(0, 4) + d.substr(5));
  else if (d.length === 12) set.add(d.substr(0, 4) + '9' + d.substr(4));
  return [...set];
}

// mapa de quem tem WhatsApp, indexado por TODAS as variantes
const existe = {};
for (const it of lista) {
  const num = digits(it && (it.number || it.jid));
  if (num && it.exists === true) for (const v of variantes(num)) existe[v] = true;
}

const rows = $('Monta números (Expirados)').first().json.rows;

// 1 registro por telefone e anota tem_whatsapp (nao descarta os sem WA:
// eles precisam ser marcados no banco pra nao voltar todo dia)
const porTelefone = {};
for (const r of rows) {
  const k = digits(r.telefone);
  if (!porTelefone[k]) porTelefone[k] = r;
}
const unicas = Object.values(porTelefone).map(r => ({
  ...r,
  tem_whatsapp: variantes(r.telefone).some(v => existe[v] === true)
}));

// GARANTE ate 15 COM WhatsApp -> so esses vao pro envio
const comWA = unicas.filter(r => r.tem_whatsapp).slice(0, 15);
// os SEM WhatsApp entram so pra serem marcados no banco (sem envio, sem espera)
const semWA = unicas.filter(r => !r.tem_whatsapp);
return [...comWA, ...semWA].map(r => ({ json: r }));

const item = $('Loop Expirados').item.json;

const produto    = String(item.nome_produto || 'seu produto');
const idAnuncio  = String(item.bid_id || '');

// IMPORTANTE: params na MESMA ordem das variaveis {{1}} {{2}} do template aprovado
const templateName = 'template_renovacao';
const params = [produto, idAnuncio];

// texto_log deve ser IDENTICO ao corpo aprovado (so pro historico)
const textoLog = `Ol\u00e1! Tudo bem? 😊 Sou a Iara, da AgroNegociar.\n\nNotei que o seu an\u00fancio de ${produto} (ID: ${idAnuncio}) expirou. Quer renovar? Se sim, responda SIM por aqui e colocamos ele no topo de novo! 🌱\n\nAproveitando o contato, voc\u00ea sabia que estamos de cara nova? Lan\u00e7amos uma nova vers\u00e3o da nossa plataforma!`;

const body = {
  messaging_product: 'whatsapp',
  to: String(item.telefone),
  type: 'template',
  template: {
    name: templateName,
    language: { code: 'pt_BR' },
    components: [
      { type: 'body', parameters: params.map(t => ({ type: 'text', text: String(t) })) }
    ]
  }
};

return [{
  json: {
    resultado: body,
    telefone: item.telefone,
    whatsapp_number_id: '1106728629181671',
    id: item.id,
    bid_id: item.bid_id,
    user_id: item.user_id,
    template_usado: templateName,
    texto_log: textoLog
  }
}];

